-- Migration: 2026-11-03_03_create_claims_backup_and_cleanup.sql
-- Description:
-- Create claims_backup audit table and apply safe rewrites for medical/wellness claims (Task 1.11)

BEGIN;

-- 1. Create claims_backup table
CREATE TABLE IF NOT EXISTS public.claims_backup (
  id SERIAL PRIMARY KEY,
  table_name TEXT NOT NULL,
  row_id TEXT NOT NULL,
  column_name TEXT NOT NULL,
  old_value TEXT,
  new_value TEXT,
  changed_at TIMESTAMPTZ DEFAULT NOW()
);

INSERT INTO public.claims_backup (table_name, row_id, column_name, old_value, new_value)
VALUES ('products', '1', 'description', 'YogKart Neem Wooden Comb is crafted from 100% natural neem wood, known for its antibacterial and antifungal properties. This eco-friendly comb helps reduce hair fall, prevents dandruff, and promotes healthy scalp circulation. Unlike plastic combs, it does not generate static electricity, making your hair smooth and frizz-free. Regular use helps distribute natural oils evenly from scalp to hair ends, improving shine and strength. Ideal for all hair types, this comb is durable, sustainable, and travel-friendly. It supports scalp health, reduces breakage, and enhances overall hair texture naturally without chemicals. A perfect choice for those who prefer Ayurvedic and herbal hair care solutions for long-term benefits and healthier hair growth.', 'YogKart Neem Wooden Comb is crafted from 100% natural neem wood, known for its antibacterial and antifungal properties. This eco-friendly comb helps reduce hair fall, prevents dandruff, and promotes healthy scalp circulation. Unlike plastic combs, it does not generate static electricity, making your hair smooth and frizz-free. Regular use helps distribute natural oils evenly from scalp to hair ends, improving shine and strength. Ideal for all hair types, this comb is durable, sustainable, and travel-friendly. It supports scalp health, reduces breakage, and enhances overall hair texture naturally without chemicals. A perfect choice for those who prefer Ayurvedic and herbal hair care solutions for long-term benefits and healthier healthy hair routine.');
